package com.example.examplemod.economy;

import com.example.examplemod.cargo.CargoTrainRegistry;
import com.example.examplemod.cargo.center.*;
import com.example.examplemod.economy.company.CompanyBook;
import net.minecraft.nbt.*;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.DimensionDataStorage;
import java.nio.file.*;
import java.util.*;

/** Production company policies, actual accounts and native preservation; no virtual factories. */
public final class CompanyCheck {
    private static int checks;
    private static void require(boolean result,String message){checks++;if(!result)throw new AssertionError(message);}
    private static void rejects(Runnable action,String message){boolean rejected=false;try{action.run();}catch(IllegalArgumentException|ArithmeticException expected){rejected=true;}require(rejected,message);}
    private static final class Accounts implements CargoCommerceBook.Accounts {
        final Map<OwnerRef,Long> cash=new HashMap<>();
        public long balance(OwnerRef owner){return cash.getOrDefault(owner,0L);}
        public boolean debit(OwnerRef owner,long amount){if(amount<0||amount>balance(owner))return false;cash.put(owner,balance(owner)-amount);return true;}
        public boolean canCredit(OwnerRef owner,long amount){return amount>=0&&balance(owner)<=Long.MAX_VALUE-amount;}
        public void credit(OwnerRef owner,long amount){if(!canCredit(owner,amount))throw new ArithmeticException();cash.put(owner,balance(owner)+amount);}
        public long maximum(){return 1_000_000_000;}
        public void dirty(){}
        long total(){return cash.values().stream().mapToLong(Long::longValue).sum();}
    }
    public static void main(String[] args)throws Exception{
        var config=BankCheck.class.getDeclaredMethod("config");config.setAccessible(true);config.invoke(null);net.minecraft.SharedConstants.tryDetectVersion();
        salary();salaryAmendment();personnelPermissions();shares();directorGovernance();tax();contracts();realAccounts();financialNativeStorage();ownershipStorage();
        System.out.println("PASS: "+checks+" companies payroll, governance, taxes, contracts, accounts and native storage checks");
    }
    private static void salaryAmendment(){var a=new Accounts();var b=new CompanyBook(a);UUID founder=UUID.randomUUID(),employee=UUID.randomUUID(),city=UUID.randomUUID(),id=UUID.randomUUID();long now=1000;b.create(id,founder,"Amendments",city,now);var hire=b.invite(id,founder,employee,CompanyBook.Role.WORKER,100,now);b.acceptJob(hire.id(),employee,now);var amendment=b.amendSalary(id,founder,employee,200,now+CompanyBook.DAY/2);b.payroll(now+CompanyBook.DAY);require(b.find(id).orElseThrow().salaryDebt()==100,"unaccepted salary amendment leaves original employment rate");var save=b.save();var restored=new CompanyBook(a);restored.load(save);restored.acceptJob(amendment.id(),employee,now+CompanyBook.DAY);restored.payroll(now+2*CompanyBook.DAY);require(restored.find(id).orElseThrow().salaryDebt()==300,"accepted amendment accrues old terms first and preserves old arrears");require(restored.find(id).orElseThrow().employees().stream().filter(e->e.player().equals(employee)).findFirst().orElseThrow().started()==now,"salary amendment retains continuous employment start");}
    private static void personnelPermissions(){var b=new CompanyBook(new Accounts());UUID founder=UUID.randomUUID(),manager=UUID.randomUUID(),employee=UUID.randomUUID(),id=UUID.randomUUID();b.create(id,founder,"HR",UUID.randomUUID(),1000);var invitation=b.invite(id,founder,manager,CompanyBook.Role.MANAGER,0,1000);b.acceptJob(invitation.id(),manager,1000);rejects(()->b.invite(id,manager,employee,CompanyBook.Role.ACCOUNTANT,0,1000),"personnel authority cannot create a financial delegate without SPEND permission");var worker=b.invite(id,manager,employee,CompanyBook.Role.WORKER,0,1000);b.cancelInvitation(worker.id(),manager);rejects(()->b.acceptJob(worker.id(),employee,1000),"withdrawn invitation cannot grant access later");}
    private static void salary(){
        var a=new Accounts();var b=new CompanyBook(a);UUID founder=UUID.randomUUID(),worker=UUID.randomUUID(),city=UUID.randomUUID(),id=UUID.randomUUID();long start=1_000;
        b.create(id,founder,"Works",city,start);a.credit(OwnerRef.player(founder),1000);b.deposit(id,founder,100);
        var invite=b.invite(id,founder,worker,CompanyBook.Role.WORKER,101,start);require(!b.permits(id,worker,CompanyBook.Permission.VIEW),"invitation alone grants no access or salary");
        var initialBook=b;rejects(()->initialBook.acceptJob(invite.id(),founder,start),"only invited employee accepts salary terms");b.acceptJob(invite.id(),worker,start);
        require(b.permits(id,worker,CompanyBook.Permission.VIEW)&&!b.permits(id,worker,CompanyBook.Permission.SPEND),"employee role does not grant financial access");
        b.payroll(start+CompanyBook.DAY/2);require(a.balance(OwnerRef.player(worker))==50,"partial real day salary floors and retains fraction");b.payroll(start+CompanyBook.DAY);require(a.balance(OwnerRef.player(worker))==100&&b.find(id).orElseThrow().salaryDebt()==1,"insufficient treasury becomes actual wage arrears, no emission");
        var save=b.save();b=new CompanyBook(a);b.load(save);b.payroll(start+CompanyBook.DAY);require(a.balance(OwnerRef.player(worker))==100&&b.find(id).orElseThrow().salaryDebt()==1,"restart cannot accrue or pay same period twice");
        b.payroll(start+CompanyBook.DAY/2);require(b.find(id).orElseThrow().salaryDebt()==1,"clock moving backwards cannot repeat salary");
        b.payroll(start+CompanyBook.DAY*3);require(b.find(id).orElseThrow().salaryDebt()==203,"offline elapsed days aggregate into payable obligation");
        b.deposit(id,founder,300);b.payroll(start+CompanyBook.DAY*3);require(a.balance(OwnerRef.player(worker))==303&&b.find(id).orElseThrow().salaryDebt()==0,"funded arrears pay without another salary accrual");
        b.endEmployment(id,founder,worker,start+CompanyBook.DAY*3+CompanyBook.DAY/2);long debt=b.find(id).orElseThrow().salaryDebt();b.payroll(start+CompanyBook.DAY*8);require(a.balance(OwnerRef.player(worker))==353&&b.find(id).orElseThrow().salaryDebt()==0&&debt==50,"termination prorates final day and stops future accrual");require(a.total()==1000,"salary and deposit conserve actual CR");
        var finalBook=b;rejects(()->finalBook.invite(id,founder,UUID.randomUUID(),CompanyBook.Role.DIRECTOR,0,start),"director access requires shareholder governance");
    }
    private static void shares(){
        var a=new Accounts();var b=new CompanyBook(a);UUID owner=UUID.randomUUID(),buyer=UUID.randomUUID(),city=UUID.randomUUID(),id=UUID.randomUUID();long now=1000;b.create(id,owner,"Rail Co",city,now);a.credit(OwnerRef.player(owner),1000);a.credit(OwnerRef.player(buyer),500);b.deposit(id,owner,600);
        var offer=b.offerShares(id,owner,buyer,6000,200,now,now+CompanyBook.DAY);rejects(()->b.offerShares(id,owner,UUID.randomUUID(),5000,0,now,now+CompanyBook.DAY),"pending private offers lock seller units");
        var before=b.propose(id,owner,CompanyBook.Decision.CHARTER,null,0,"Snapshot charter",now);b.acceptShares(offer.id(),buyer,now);require(a.balance(OwnerRef.player(buyer))==300&&a.balance(OwnerRef.player(owner))==600,"share payment and transfer conserve actual player balances");require(!b.permits(id,buyer,CompanyBook.Permission.SPEND)&&b.shareholder(id,buyer),"capital ownership is not employee financial authority");
        b.vote(before.id(),owner,true,now);require(b.find(id).orElseThrow().charter().equals("Snapshot charter"),"vote electorate is frozen before subsequent share transfer");
        var dividend=b.propose(id,buyer,CompanyBook.Decision.DIVIDEND,null,100,"",now);b.vote(dividend.id(),buyer,true,now);require(a.balance(OwnerRef.player(owner))==640&&a.balance(OwnerRef.player(buyer))==360&&a.balance(CompanyBook.owner(id))==500,"weighted dividends divide all and only approved funds");
        b.externalDebt(o->500);var blocked=b.propose(id,buyer,CompanyBook.Decision.DIVIDEND,null,1,"",now);rejects(()->b.vote(blocked.id(),buyer,true,now),"road debts reserve distributable balance");require(a.balance(CompanyBook.owner(id))==500,"blocked dividend leaves cash intact");
        var saved=b.save();var restored=new CompanyBook(a);restored.load(saved);require(restored.find(id).orElseThrow().totalShares()==10000&&restored.votes().stream().anyMatch(v->v.id().equals(dividend.id())&&v.state().equals("EXECUTED")),"share ownership and executed vote survive reload");
        rejects(()->restored.acceptShares(offer.id(),buyer,now),"completed private deal cannot pay or transfer again");require(a.total()==1500,"private shares and distributions conserve CR");
        var staleOffer=restored.offerShares(id,owner,buyer,100,1,now,now+CompanyBook.DAY);var issue=restored.propose(id,buyer,CompanyBook.Decision.ISSUE_SHARES,buyer,100,"",now);restored.vote(issue.id(),buyer,true,now);long beforePurchase=a.balance(OwnerRef.player(buyer));rejects(()->restored.acceptShares(staleOffer.id(),buyer,now),"share offer cannot silently dilute its agreed percentage before acceptance");require(a.balance(OwnerRef.player(buyer))==beforePurchase,"changed share terms cannot debit buyer");
    }
    private static void tax(){var a=new Accounts();var b=new CompanyBook(a);UUID owner=UUID.randomUUID(),id=UUID.randomUUID(),city=UUID.randomUUID();b.create(id,owner,"Tax works",city,1000);b.tax(city,1000);for(int i=0;i<10;i++)b.revenue(CompanyBook.stable(id,"receipt/"+i),id,1,1000);require(a.balance(CompanyBook.owner(id))==9&&a.balance(new OwnerRef(OwnerRef.Kind.CITY,city))==1,"splitting revenue cannot round all tax away");require(b.find(id).orElseThrow().revenue()==10&&b.find(id).orElseThrow().taxPaid()==1,"actual receipt statistics use gross revenue");b.revenue(CompanyBook.stable(id,"receipt/0"),id,1,1000);require(a.total()==10,"stable source receipt cannot pay or tax again");var save=b.save();var restored=new CompanyBook(a);restored.load(save);restored.revenue(CompanyBook.stable(id,"receipt/0"),id,1,2000);require(a.total()==10,"tax idempotency survives save/load");a.credit(OwnerRef.player(owner),50);restored.deposit(id,owner,50);require(restored.find(id).orElseThrow().taxPaid()==1,"capital deposit is not taxable revenue");restored.tax(city,2000);restored.revenue(UUID.randomUUID(),id,10,2000);require(a.balance(new OwnerRef(OwnerRef.Kind.CITY,city))==3,"new tax policy applies only to new paid revenue");}
    private static void contracts(){var a=new Accounts();var b=new CompanyBook(a);UUID owner=UUID.randomUUID(),id=UUID.randomUUID(),city=UUID.randomUUID();b.create(id,owner,"Contracts",city,1000);var contract=b.contract(id,owner,CompanyBook.ContractKind.SUPPLY,OwnerRef.player(UUID.randomUUID()),UUID.randomUUID(),40,10,"Physical Cargo order",2000,1000);b.acceptContract(contract.id(),1001);b.completeContract(contract.id());b.completeContract(contract.id());require(b.contracts().getFirst().state()==CompanyBook.ContractState.COMPLETED&&a.total()==0,"contract observes existing Cargo payment, never issues a second reward");rejects(()->b.cancelContract(contract.id(),owner),"completed obligation cannot revert to offer");}
    private static void directorGovernance(){
        var accounts=new Accounts();var b=new CompanyBook(accounts);UUID founder=UUID.randomUUID(),buyer=UUID.randomUUID(),external=UUID.randomUUID(),worker=UUID.randomUUID(),id=UUID.randomUUID();long now=1000;b.create(id,founder,"Governed Co",UUID.randomUUID(),now);var hire=b.invite(id,founder,worker,CompanyBook.Role.WORKER,50,now);b.acceptJob(hire.id(),worker,now);
        var sale=b.offerShares(id,founder,buyer,CompanyBook.INITIAL_SHARES,0,now,now+CompanyBook.DAY);b.acceptShares(sale.id(),buyer,now);require(b.shareholder(id,buyer)&&!b.permits(id,buyer,CompanyBook.Permission.SPEND),"buying all shares alone does not silently grant operational access");
        var self=b.propose(id,buyer,CompanyBook.Decision.DIRECTOR,buyer,0,"Owner accepts directorship by voting yes",now);b.vote(self.id(),buyer,true,now);require(b.permits(id,buyer,CompanyBook.Permission.SPEND)&&!b.permits(id,founder,CompanyBook.Permission.SPEND),"100 percent owner can appoint consenting self without incumbent invitation or veto");var newDirector=b.find(id).orElseThrow().employees().stream().filter(e->e.player().equals(buyer)).findFirst().orElseThrow();require(newDirector.role()==CompanyBook.Role.DIRECTOR&&newDirector.salary()==0,"new majority-owner director membership creates no unsolicited salary obligation");
        var outsider=b.propose(id,buyer,CompanyBook.Decision.DIRECTOR,external,0,"External appointment",now);b.vote(outsider.id(),buyer,true,now);require(b.permits(id,buyer,CompanyBook.Permission.SPEND)&&!b.permits(id,external,CompanyBook.Permission.VIEW),"approved external appointment retains incumbent until target explicitly accepts");var appointment=b.invites().stream().filter(i->outsider.id().equals(i.appointment())).findFirst().orElseThrow();rejects(()->b.cancelInvitation(appointment.id(),buyer),"incumbent HR cannot veto a shareholder-approved director invitation");var restored=new CompanyBook(accounts);restored.load(b.save());restored.acceptJob(appointment.id(),external,now+CompanyBook.DAY);require(restored.permits(id,external,CompanyBook.Permission.SPEND)&&!restored.permits(id,buyer,CompanyBook.Permission.SPEND),"external acceptance after restart atomically replaces incumbent director");require(restored.find(id).orElseThrow().salaryDebt()==50,"appointment preserves accrued existing employee salary debt");
        var promote=restored.propose(id,buyer,CompanyBook.Decision.DIRECTOR,worker,0,"Existing employee must consent",now+CompanyBook.DAY);restored.vote(promote.id(),buyer,true,now+CompanyBook.DAY);var employeeInvite=restored.invites().stream().filter(i->promote.id().equals(i.appointment())).findFirst().orElseThrow();restored.acceptJob(employeeInvite.id(),worker,now+2*CompanyBook.DAY);var promoted=restored.find(id).orElseThrow().employees().stream().filter(e->e.player().equals(worker)).findFirst().orElseThrow();require(promoted.role()==CompanyBook.Role.DIRECTOR&&promoted.salary()==50&&promoted.started()==now&&promoted.arrears()==100,"consented promotion preserves salary terms, start and accrued arrears");
        var stale=restored.propose(id,buyer,CompanyBook.Decision.DIRECTOR,external,0,"Superseded appointment",now+2*CompanyBook.DAY);restored.vote(stale.id(),buyer,true,now+2*CompanyBook.DAY);var staleInvite=restored.invites().stream().filter(i->stale.id().equals(i.appointment())).findFirst().orElseThrow();var replacement=restored.propose(id,buyer,CompanyBook.Decision.DIRECTOR,buyer,0,"Latest majority decision",now+2*CompanyBook.DAY);restored.vote(replacement.id(),buyer,true,now+2*CompanyBook.DAY);rejects(()->restored.acceptJob(staleInvite.id(),external,now+2*CompanyBook.DAY),"superseded external appointment cannot override a newer majority decision");require(restored.votes().stream().anyMatch(v->v.id().equals(stale.id())&&v.state().equals("SUPERSEDED"))&&restored.permits(id,buyer,CompanyBook.Permission.SPEND),"governance preserves an auditable superseded decision and current authority");require(accounts.total()==0,"director changes never issue or move company money");
    }
    private static void realAccounts(){var e=new EconomyManager();UUID actor=UUID.randomUUID(),id=UUID.randomUUID(),city=UUID.randomUUID();e.adminSetWallet(actor,1000);e.companies().create(id,actor,"Actual accounts",city,1000);e.companies().deposit(id,actor,100);require(e.wallet(id)==0&&e.wallet(actor)==900&&e.accounts().balance(CompanyBook.owner(id))==100,"COMPANY has separate account, never a player wallet with company UUID");e.companies().tax(city,2500);require(e.accounts().canReceivePayments(Map.of(CompanyBook.owner(id),40L),Map.of(CompanyBook.owner(id),5L)),"combined tax and refund preflight is prepared");e.accounts().revenue(UUID.randomUUID(),CompanyBook.owner(id),40);e.accounts().credit(CompanyBook.owner(id),5);require(e.accounts().balance(CompanyBook.owner(id))==135&&e.treasury(city)==10,"revenue splits tax while refund stays untaxed");var save=e.save(new CompoundTag(),null);require(save.getCompound("Companies").getInt("Version")==1&&save.getList("CompanyAccounts",10).size()==1,"company ledger and balance share a native financial save");var unknown=new OwnerRef(OwnerRef.Kind.FOREIGN_TRADE,UUID.randomUUID());rejects(()->e.accounts().balance(unknown),"unknown internal trade UUID cannot access a financial account");var future=save.getCompound("Companies").copy();future.putInt("Version",2);rejects(()->new CompanyBook(e.accounts()).load(future),"future company data fails closed");}
    private static void ownershipStorage()throws Exception{
        var legacy=new CompoundTag();legacy.putInt("Version",1);require(CargoOwners.load(legacy,null).save(new CompoundTag(),null).getInt("Version")==2,"v1 ACL remains readable and upgrades explicitly");
        var company=CompanyBook.owner(UUID.randomUUID());var access=new CargoOwners.Access(OwnerRef.player(UUID.randomUUID()),CargoTrainRegistry.AccessMode.RESTRICTED,Set.of(),Set.of(),Set.of(company.id()));require(CargoOwners.permits(null,company,access),"explicit restricted company ACL works without pretending company UUID is city/player");
        var dir=Files.createTempDirectory(Path.of("").toAbsolutePath(),"company-native-");try{var raw=new CompoundTag();raw.putInt("Version",3);raw.putString("UnknownCompanyAssets","retain");var disk=new CompoundTag();disk.put("data",raw);NbtUtils.addCurrentDataVersion(disk);var file=dir.resolve("ccec_cargo_ownership.dat");NbtIo.writeCompressed(disk,file);var storage=new DimensionDataStorage(dir.toFile(),null,null);boolean rejected=false;try{CargoOwners.fromStorage(storage);}catch(IllegalStateException expected){rejected=true;}require(rejected,"native storage cannot replace unreadable future company ownership with empty permissions");var cached=storage.get(new SavedData.Factory<CargoOwners>(CargoOwners::new,(tag,registries)->{throw new AssertionError("native cache lost");}),"ccec_cargo_ownership");require(cached!=null&&cached.save(new CompoundTag(),null).equals(raw),"rejected company ownership preserves all original NBT");Files.delete(file);cached.setDirty();storage.save();net.neoforged.neoforge.common.IOUtilities.waitUntilIOWorkerComplete();require(NbtIo.readCompressed(file,NbtAccounter.unlimitedHeap()).getCompound("data").equals(raw),"forced native save cannot erase rejected company ownership");}finally{net.neoforged.neoforge.common.IOUtilities.waitUntilIOWorkerComplete();if(!dir.toRealPath().startsWith(Path.of("").toRealPath()))throw new AssertionError("unsafe fixture cleanup");try(var paths=Files.walk(dir)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(path);}}
    }
    private static void financialNativeStorage()throws Exception{
        var economy=new EconomyManager();UUID actor=UUID.randomUUID(),id=UUID.randomUUID();economy.adminSetWallet(actor,1000);economy.companies().create(id,actor,"Persistent Co",UUID.randomUUID(),1000);economy.companies().deposit(id,actor,100);var valid=economy.save(new CompoundTag(),null);
        var dir=Files.createTempDirectory(Path.of("").toAbsolutePath(),"company-financial-");try{var file=dir.resolve("createcityexpansioncore_economy.dat");writeData(file,valid);var loaded=EconomyManager.fromStorage(new DimensionDataStorage(dir.toFile(),null,null));require(loaded.wallet(actor)==900&&loaded.wallet(id)==0&&loaded.accounts().balance(CompanyBook.owner(id))==100,"native save reload preserves company money separately from personal wallets");
            var invalid=valid.copy();invalid.getList("CompanyAccounts",10).getCompound(0).putLong("Amount",-100);writeData(file,invalid);boolean rejected=false;try{EconomyManager.fromStorage(new DimensionDataStorage(dir.toFile(),null,null));}catch(IllegalStateException expected){rejected=true;}require(rejected,"invalid new company balance cannot silently disappear into a zero account");
            var future=valid.copy();future.getCompound("Companies").putInt("Version",2);writeData(file,future);var storage=new DimensionDataStorage(dir.toFile(),null,null);rejected=false;try{EconomyManager.fromStorage(storage);}catch(IllegalStateException expected){rejected=true;}require(rejected,"unknown nested company codec rejects the whole financial registry");var cached=storage.get(new SavedData.Factory<EconomyManager>(EconomyManager::new,(tag,registries)->{throw new AssertionError("cache lost");}),"createcityexpansioncore_economy");require(cached!=null&&cached.save(new CompoundTag(),null).equals(future),"nested company codec rejection retains original balances and obligations");Files.delete(file);cached.setDirty();storage.save();net.neoforged.neoforge.common.IOUtilities.waitUntilIOWorkerComplete();require(NbtIo.readCompressed(file,NbtAccounter.unlimitedHeap()).getCompound("data").equals(future),"forced save after company codec failure cannot overwrite future financial data");
        }finally{net.neoforged.neoforge.common.IOUtilities.waitUntilIOWorkerComplete();if(!dir.toRealPath().startsWith(Path.of("").toRealPath()))throw new AssertionError("unsafe fixture cleanup");try(var paths=Files.walk(dir)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(path);}}
    }
    private static void writeData(Path file,CompoundTag data)throws Exception{var root=new CompoundTag();root.put("data",data.copy());NbtUtils.addCurrentDataVersion(root);NbtIo.writeCompressed(root,file);}
}
